  function escapeHtml(text) {
    return String(text).replace(/[&<>"']/g, function (ch) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      }[ch];
    });
  }

  function getErrorMessage(err) {
    if (err instanceof Error) return err.message;
    if (typeof err === "string") return err;
    try {
      return JSON.stringify(err);
    } catch (e) {
      return String(err);
    }
  }

  function formatBytes(bytes) {
    if (bytes === 0) return "0 B";
    const units = ["B", "KB", "MB", "GB"];
    const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
    return (bytes / Math.pow(1024, i)).toFixed(i ? 2 : 0) + " " + units[i];
  }

  function getFileExtension(name) {
    const idx = String(name).lastIndexOf(".");
    return idx > -1 ? String(name).slice(idx + 1).toLowerCase() : "";
  }

  function getDeviceInfo() {
    const ua = navigator.userAgent || "";
    let browser = tr("logUnknown", "unknown");
    if (/Edg\//.test(ua)) browser = "Edge";
    else if (/OPR\//.test(ua)) browser = "Opera";
    else if (/Chrome\//.test(ua)) browser = "Chrome";
    else if (/Firefox\//.test(ua)) browser = "Firefox";
    else if (/Safari\//.test(ua)) browser = "Safari";
    let os = tr("logUnknown", "unknown");
    if (/Windows NT 10\.[0-9]/i.test(ua) || /Windows NT 11/i.test(ua)) os = "Windows 10/11";
    else if (/Windows/i.test(ua)) os = "Windows";
    else if (/Android/i.test(ua)) os = "Android";
    else if (/iPhone|iPad|iPod/i.test(ua)) os = "iOS";
    else if (/Mac OS X/i.test(ua)) os = "macOS";
    else if (/Linux/i.test(ua)) os = "Linux";
    const threads = navigator.hardwareConcurrency || 1;
    const sab = typeof SharedArrayBuffer !== "undefined" && window.crossOriginIsolated === true;
    return { browser: browser, os: os, threads: threads, sab: sab };
  }

  function addLog(message) {
    const line = document.createElement("div");
    line.className = "log-line";
    line.innerHTML =
      '<span class="log-time">[' + new Date().toLocaleTimeString() + "]</span>" + escapeHtml(message);
    els.logArea.appendChild(line);
    els.logArea.scrollTop = els.logArea.scrollHeight;
  }

  function setProgress(pct) {
    const value = Math.max(0, Math.min(100, pct));
    els.progressBar.style.width = value + "%";
    els.progressLabel.textContent = Math.round(value) + "%";
  }

  async function copyLog() {
    const text = Array.from(els.logArea.querySelectorAll(".log-line"))
      .map(function (line) {
        return line.textContent.trim();
      })
      .join("\n");
    if (!text) {
      addLog(tr("logLogEmpty", "Log kosong, tidak ada yang disalin."));
      return;
    }
    try {
      await navigator.clipboard.writeText(text);
      addLog(tr("logLogCopied", "Log disalin ke clipboard."));
    } catch (err) {
      addLog(tr("logLogCopyFail", "Gagal menyalin log: ") + err.message);
    }
  }

  async function clearAppCache() {
    els.logArea.innerHTML = "";
    try {
      localStorage.clear();
      sessionStorage.clear();
      if ("caches" in window) {
        const keys = await caches.keys();
        await Promise.all(keys.map(function (key) {
          return caches.delete(key);
        }));
      }
      if ("serviceWorker" in navigator) {
        const registrations = await navigator.serviceWorker.getRegistrations();
        await Promise.all(registrations.map(function (registration) {
          return registration.unregister();
        }));
      }
    } catch (err) {
      addLog(tr("logClearFail", "Error membersihkan cache: ") + err.message);
    }
  }

  function downloadFile(data, fileName) {
    const blob = data instanceof Blob ? data : new Blob([data]);
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 5000);
    addLog(tr("logDone", "Proses selesai.") + " | " + tr("logDownloadReady", "File siap diunduh: ") + fileName);
  }

  function toolStatus(el, cls, msg) {
    el.textContent = msg;
    el.className = "tool-status" + (cls ? " " + cls : "");
  }

  async function extractMp3(file) {
    const ffmpeg = await loadFfmpeg();
    const ext = getFileExtension(file.name) || "mp4";
    const inputName = "tool_input_" + Date.now() + "." + ext;
    const outputName = "tool_output_" + Date.now() + ".mp3";
    addLog("[1/3] " + tr("logStep1", "Memuat data video..."));
    await ffmpeg.writeFile(inputName, new Uint8Array(await file.arrayBuffer()));
    addLog("[2/3] " + tr("logStep2", "Optimasi kualitas..."));
    addLog(tr("logFilters", "FFmpeg filters: ") + "-vn -acodec libmp3lame");
    await ffmpeg.exec(["-y", "-i", inputName, "-vn", "-acodec", "libmp3lame", "-q:a", "2", outputName]);
    addLog("[3/3] " + tr("logStep3", "Encoding & menyimpan..."));
    const data = await ffmpeg.readFile(outputName);
    await removeFfmpegFiles(ffmpeg, [inputName, outputName]);
    return data;
  }

  function detectVideoFormat(file) {
    let ext = getFileExtension(file.name) || "";
    if (!ext && file.type) {
      const mt = file.type.toLowerCase();
      if (mt.includes("mp4")) ext = "mp4";
      else if (mt.includes("avi") || mt.includes("x-msvideo")) ext = "avi";
      else if (mt.includes("quicktime")) ext = "mov";
      else if (mt.includes("x-matroska")) ext = "mkv";
      else if (mt.includes("webm")) ext = "webm";
      else if (mt.includes("wmv") || mt.includes("x-ms-wmv")) ext = "wmv";
    }
    return (ext || "mp4").toLowerCase();
  }

  function getConvertArgs(target) {
    const t = String(target).toLowerCase();
    if (t === "avi") return ["-c:v", "mpeg4", "-qscale:v", "5", "-c:a", "libmp3lame", "-q:a", "2"];
    if (t === "mov") return ["-c:v", "libx264", "-preset", "veryfast", "-crf", "22", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k"];
    if (t === "mkv") return ["-c:v", "libx264", "-preset", "veryfast", "-crf", "22", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "192k"];
    if (t === "webm") return ["-c:v", "libvpx-vp9", "-crf", "32", "-b:v", "0", "-c:a", "libopus", "-b:a", "128k", "-row-mt", "1", "-threads", String(Math.min(4, navigator.hardwareConcurrency || 2))];
    if (t === "wmv") return ["-c:v", "wmv2", "-qscale:v", "2", "-c:a", "wmav2", "-b:a", "192k"];
    return ["-c:v", "libx264", "-preset", "ultrafast", "-crf", "23", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "128k", "-movflags", "+faststart"];
  }

  async function convertVideo(file, targetFormat) {
    if (file.size > MAX_FILE_BYTES) {
      throw new Error(tr("logTooBig", "Error: File terlalu besar (") + formatBytes(file.size) + tr("logTooBig2", "). Maksimal 1500 MB."));
    }
    const srcExt = detectVideoFormat(file);
    const tgt = String(targetFormat).toLowerCase();
    if (srcExt === tgt) {
      throw new Error(tr("toolConvertSame", "Format target sama dengan format asal. Pilih format lain."));
    }
    const ffmpeg = await loadFfmpeg();
    const inputName = "conv_input_" + Date.now() + "." + srcExt;
    const outputName = "conv_output_" + Date.now() + "." + tgt;
    addLog("[1/3] " + tr("logStep1", "Memuat data video...") + " (" + srcExt.toUpperCase() + " → " + tgt.toUpperCase() + ")");
    await ffmpeg.writeFile(inputName, new Uint8Array(await file.arrayBuffer()));
    addLog("[2/3] " + tr("logStep2", "Optimasi kualitas..."));
    const args = getConvertArgs(tgt);
    const threads = String(Math.min(4, navigator.hardwareConcurrency || 2));
    // inject threads if not already in args
    const hasThreads = args.indexOf("-threads") !== -1;
    const fullArgs = hasThreads ? args : ["-threads", threads].concat(args);
    addLog(tr("logFilters", "FFmpeg filters: ") + fullArgs.join(" "));
    await ffmpeg.exec(["-y", "-i", inputName].concat(fullArgs).concat([outputName]));
    addLog("[3/3] " + tr("logStep3", "Encoding & menyimpan..."));
    const data = await ffmpeg.readFile(outputName);
    await removeFfmpegFiles(ffmpeg, [inputName, outputName]);
    return data;
  }

  function parseCutTime(str) {
    const s = String(str).trim();
    if (!s) return NaN;
    if (/^\d+(\.\d+)?$/.test(s)) return parseFloat(s);
    const parts = s.split(":").map(function (p) { return p.trim(); });
    if (parts.some(function (p) { return p === "" || isNaN(p); })) return NaN;
    let sec = 0;
    for (let i = 0; i < parts.length; i++) {
      const v = parseFloat(parts[i]);
      if (!isFinite(v) || v < 0) return NaN;
      sec = sec * 60 + v;
    }
    return sec;
  }

  function formatCutTime(sec) {
    if (!isFinite(sec) || sec < 0) return "00:00";
    sec = Math.round(sec);
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return (m < 10 ? "0" + m : String(m)) + ":" + (s < 10 ? "0" + s : String(s));
  }

  function getVideoDuration(file) {
    return new Promise(function (resolve) {
      try {
        const url = URL.createObjectURL(file);
        const v = document.createElement("video");
        v.preload = "metadata";
        v.onloadedmetadata = function () {
          URL.revokeObjectURL(url);
          const d = isFinite(v.duration) ? v.duration : 0;
          resolve(d);
        };
        v.onerror = function () {
          URL.revokeObjectURL(url);
          resolve(0);
        };
        v.src = url;
        setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e) {} resolve(0); }, 5000);
      } catch (e) { resolve(0); }
    });
  }

  async function cutVideo(file, startSec, endSec) {
    if (file.size > MAX_FILE_BYTES) {
      throw new Error(tr("logTooBig", "Error: File terlalu besar (") + formatBytes(file.size) + tr("logTooBig2", "). Maksimal 1500 MB."));
    }
    if (!isFinite(startSec) || !isFinite(endSec) || startSec < 0 || endSec <= startSec) {
      throw new Error(tr("toolCutInvalid", "Waktu tidak valid. Gunakan detik atau mm:ss (contoh 01:30)."));
    }
    const srcExt = detectVideoFormat(file);
    const ffmpeg = await loadFfmpeg();
    const inputName = "cut_input_" + Date.now() + "." + srcExt;
    const outputName = "cut_output_" + Date.now() + "." + srcExt;
    addLog("[1/3] " + tr("logStep1", "Memuat data video...") + " (" + formatCutTime(startSec) + " → " + formatCutTime(endSec) + ")");
    await ffmpeg.writeFile(inputName, new Uint8Array(await file.arrayBuffer()));
    addLog("[2/3] " + tr("logStep2", "Optimasi kualitas..."));
    const duration = endSec - startSec;
    const threads = String(Math.min(4, navigator.hardwareConcurrency || 2));
    // Fast path: stream copy (instant) for 0-3s or any short clip. Accurate enough for most, ultra fast.
    let usedCopy = false;
    try {
      addLog(tr("logFilters", "FFmpeg filters: ") + "-ss " + startSec + " -t " + duration + " -c copy (fast)");
      await ffmpeg.exec(["-y", "-ss", String(startSec), "-i", inputName, "-t", String(duration), "-c", "copy", "-avoid_negative_ts", "make_zero", outputName]);
      usedCopy = true;
    } catch (copyErr) {
      addLog("[Cut] copy gagal, fallback re-encode ultra cepat: " + getErrorMessage(copyErr));
    }
    if (!usedCopy) {
      addLog(tr("logFilters", "FFmpeg filters: ") + "-ss " + startSec + " -t " + duration + " -c:v libx264 ultrafast (fallback)");
      await ffmpeg.exec(["-y", "-ss", String(startSec), "-i", inputName, "-t", String(duration), "-threads", threads, "-c:v", "libx264", "-preset", "ultrafast", "-crf", "23", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "128k", "-movflags", "+faststart", outputName]);
    }
    addLog("[3/3] " + tr("logStep3", "Encoding & menyimpan..."));
    const data = await ffmpeg.readFile(outputName);
    await removeFfmpegFiles(ffmpeg, [inputName, outputName]);
    return data;
  }

  async function rescaleVideo(file, targetHeight) {
    if (!file) throw new Error(tr("toolRescaleNeed", "Pilih video terlebih dahulu."));
    if (file.size > MAX_FILE_BYTES) throw new Error(tr("logTooBig", "Error: File terlalu besar (") + formatBytes(file.size) + tr("logTooBig2", "). Maksimal 1500 MB."));
    const tgt = parseInt(targetHeight,10);
    if (![360,480,720].includes(tgt)) throw new Error("Target tidak valid.");
    const ffmpeg = await loadFfmpeg();
    const srcExt = detectVideoFormat(file);
    const inputName = "rescale_in_" + Date.now() + "." + srcExt;
    const outputName = "rescale_out_" + Date.now() + ".mp4";
    const vf = "scale=-2:" + tgt + ":flags=lanczos:force_original_aspect_ratio=decrease,setsar=1,format=yuv420p";
    addLog("[1/3] " + tr("logStep1", "Memuat data video...") + " (" + tgt + "p)");
    await ffmpeg.writeFile(inputName, new Uint8Array(await file.arrayBuffer()));
    addLog("[2/3] " + tr("logStep2", "Optimasi kualitas..."));
    addLog(tr("logFilters", "FFmpeg filters: ") + vf + " (no upscale)");
    const threads = String(Math.min(4, navigator.hardwareConcurrency || 2));
    try {
      await ffmpeg.exec(["-y","-i",inputName,"-threads",threads,"-vf",vf,"-c:v","libx264","-preset","veryfast","-crf","22","-pix_fmt","yuv420p","-c:a","aac","-b:a","128k","-movflags","+faststart",outputName]);
    } catch (e) {
      addLog("[Rescale] fallback copy audio: " + getErrorMessage(e));
      await ffmpeg.exec(["-y","-i",inputName,"-threads",threads,"-vf",vf,"-c:v","libx264","-preset","veryfast","-crf","22","-pix_fmt","yuv420p","-c:a","copy","-movflags","+faststart",outputName]);
    }
    addLog("[3/3] " + tr("logStep3", "Encoding & menyimpan..."));
    const data = await ffmpeg.readFile(outputName);
    await removeFfmpegFiles(ffmpeg, [inputName, outputName]);
    return data;
  }

  function makeStatus(ok, warn) {
    return { icon: ok ? "\u2705" : warn ? "\u26A0\uFE0F" : "\u274C", ok: ok, warn: warn };
  }

  function showTopNotif(msg){
    const el=document.getElementById("topNotif");
    if(!el) return;
    try{ document.body.appendChild(el); }catch(e){ console.warn(e); }
    el.textContent=msg;
    el.hidden=false;
    void el.offsetHeight;
    el.classList.add("show");
    clearTimeout(showTopNotif._t);
    showTopNotif._t=setTimeout(function(){ el.classList.remove("show"); setTimeout(function(){ el.hidden=true; },260); }, 4000);
  }
  function showToast(msg) {
    const toast = document.getElementById("appToast");
    if (!toast) return;
    try{ document.body.appendChild(toast); }catch(e){ console.warn(e); }
    toast.textContent = msg;
    toast.style.zIndex = "2147483647";
    toast.style.top = "calc(10px + env(safe-area-inset-top, 0px))";
    toast.classList.add("show");
    clearTimeout(showToast._t);
    showToast._t = setTimeout(function () {
      toast.classList.remove("show");
    }, 3500);
  }

  function setProcessingFlag(on) {
    if (on) {
      isProcessing = true;
      toolProcessingCount++;
    } else {
      toolProcessingCount = Math.max(0, toolProcessingCount - 1);
      if (toolProcessingCount === 0) isProcessing = false;
    }
  }

  function isBusy() {
    if (!isProcessing) return false;
    // cek apakah memang ada proses terlihat (progress bar atau status tools)
    const hasMain = els.progressWrap && !els.progressWrap.hidden;
    const statuses = [els.toolMp3Status, els.toolConvertStatus, els.toolCutStatus, els.toolRescaleStatus];
    const hasTool = statuses.some(function(el){ return el && el.textContent.indexOf("Memproses") !== -1; });
    if (hasMain || hasTool) return true;
    // stale flag (mis. setelah sukses tapi flag belum reset) → auto-reset
    isProcessing = false;
    toolProcessingCount = 0;
    return false;
  }

  window.addEventListener("beforeunload", function (e) {
    let busy = isProcessing || !els.progressWrap.hidden;
    if (!busy) {
      const mp3Busy = els.toolMp3Run && !els.toolMp3Run.hidden && els.toolMp3Status && els.toolMp3Status.textContent === tr("processing", "Memproses...");
      const convBusy = els.toolConvertRun && !els.toolConvertRun.hidden && els.toolConvertStatus && els.toolConvertStatus.textContent === tr("processing", "Memproses...");
      const cutBusy = els.toolCutRun && !els.toolCutRun.hidden && els.toolCutStatus && els.toolCutStatus.textContent === tr("processing", "Memproses...");
      busy = mp3Busy || convBusy || cutBusy;
    }
    if (busy) {
      const msg = lang === "en" ? "Process is still running. Are you sure you want to leave? Progress will be lost." : "Proses masih berjalan. Yakin mau keluar? Progress akan hilang.";
      e.preventDefault();
      e.returnValue = msg;
      return msg;
    }
  });

  function setCompressGuard() {
    // no blocking for new 3-level compress; kept for compat
  }

  function setupSegmented(container, key) {
    if (!container) return;
    // delegate + direct fallback for robustness (fix "gamau pilih")
    function activate(btn){
      if (!btn) return;
      if (isProcessing) { try{ showToast(tr("processing","Memproses...")); }catch(e){ console.warn(e); } return; }
      container.querySelectorAll(".qm-seg-btn,.seg-btn").forEach(function (b) {
        b.classList.toggle("active", b === btn);
      });
      state[key] = btn.dataset.value;
      if (state.version === "v1") state.version = "wmv";
      if (state.version === "v3") state.version = "binary";
      if (state.compress === "on") state.compress = "1080p";
      if (state.compress === "off" && key==="compress" && !btn.dataset.value) state.compress="off";
      if (key==="version") setCompressVisibility();
      updateMethodDescription();
      updateQmInfo();
    }
    container.addEventListener("click", function (e) {
      const btn = e.target.closest(".qm-seg-btn") || e.target.closest(".seg-btn");
      if (!btn) return;
      e.preventDefault();
      activate(btn);
    });
    // direct per-button listener as backup (handles pointer-events / bubbling issues)
    container.querySelectorAll(".qm-seg-btn,.seg-btn").forEach(function(b){
      b.addEventListener("click", function(e){ e.stopPropagation(); activate(b); });
    });
  }

  const METHOD_DESCRIPTIONS = {
    wmv: "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "wmv-off": "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "wmv-720p": "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "wmv-1080p": "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "binary-off": "Melakukan patch MP4 murni tanpa proses encode ulang sehingga kualitas asli tetap terjaga sepenuhnya. Tidak terjadi kompresi dan tidak ada penurunan kualitas.",
    "binary-720p": "Mengompresi video ke codec H.264 pada resolusi HD 720p dengan pengaturan bitrate yang dioptimalkan untuk keseimbangan kualitas dan ukuran file. Dilanjutkan dengan patch HD agar tetap tajam saat diunggah. Direkomendasikan untuk menghemat kuota.",
    "binary-1080p": "Mengompresi video ke codec H.264 pada resolusi Full HD 1080p dengan batas bitrate tinggi untuk menjaga ketajaman detail dan pergerakan. Dilanjutkan dengan patch HD untuk menjaga kualitas tetap optimal. <span class=\"tiktok-rec\">Sangat direkomendasikan untuk TikTok.</span>",
    "fps-off": "Melakukan patch frame rate tanpa mengubah resolusi. Hanya melakukan normalisasi frame rate agar pemutaran video lebih stabil.",
    "fps-720p": "Melakukan normalisasi frame rate dan penyesuaian resolusi ke 720p untuk menghasilkan pemutaran yang stabil dengan ukuran file yang lebih efisien.",
    "fps-1080p": "Melakukan normalisasi frame rate ke 60, 30 atau 24 fps dengan batas resolusi 1080p untuk menjaga kehalusan gerakan dan kompatibilitas pemutaran.",
    v1: "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "v1-on": "Mengodekan ulang video ke codec WMV2 dengan mempertahankan resolusi asli (lossy compression).",
    "v3-on": "Mengompresi video ke codec H.264 pada resolusi Full HD 1080p dengan pengaturan yang dioptimalkan untuk kualitas HD dan ukuran file yang lebih kecil.",
    "v3-off": "Melakukan patch MP4 murni tanpa proses encode ulang sehingga kualitas asli tetap terjaga sepenuhnya.",
  };

  function updateMethodDescription() {
    const ver = state.version === "v1" ? "wmv" : state.version === "v3" ? "binary" : state.version;
    const cmp = state.compress === "on" ? "1080p" : state.compress === "off" ? "off" : state.compress;
    const key = ver + "-" + cmp;
    const fallback = METHOD_DESCRIPTIONS[key] || METHOD_DESCRIPTIONS[ver] || METHOD_DESCRIPTIONS["binary-1080p"];
    els.methodDesc.innerHTML = tr("method-" + key, fallback);
    // also handle legacy keys for i18n compat
    if (els.methodDesc.innerHTML === key) els.methodDesc.innerHTML = fallback;
  }

  function updateQmInfo() {
    if (!els.qmInfoFormat) return;
    const m = state.version;
    const c = state.compress;
    if (m === "wmv") {
      els.qmInfoFormat.textContent = ".wmv";
      els.qmInfoCodec.textContent = "WMV2";
    } else if (m === "fps") {
      els.qmInfoFormat.textContent = ".mp4";
      els.qmInfoCodec.textContent = "H.264 / FPS";
    } else {
      els.qmInfoFormat.textContent = ".mp4";
      els.qmInfoCodec.textContent = "H.264";
    }
    if (c === "off") els.qmInfoRes.textContent = "Original";
    else if (c === "720p") els.qmInfoRes.textContent = "720p";
    else els.qmInfoRes.textContent = "1080p";
  }

  function setCompressVisibility() {
    if (state.version === "v1") state.version = "wmv";
    if (state.version === "v3") state.version = "binary";
    if (state.compress === "on") state.compress = "1080p";
    // compress & fixAudio hanya untuk BINARY (v3) — tiru sumber 100% (tool-dynamic-options)
    const isBinary = state.version === "binary" || state.version === "v3";
    if (els.compressRow) els.compressRow.hidden = !isBinary;
    if (els.qmFixAudio) {
      const row = els.qmFixAudio.closest('.qm-checkbox') || els.qmFixAudio.parentElement;
      if (row) row.hidden = !isBinary;
      if (!isBinary) { els.qmFixAudio.checked = false; state.fixAudio = false; }
    }
    updateQmInfo();
  }

  function walkBoxes(dv, u8, start, end, cb) {
    let offset = start;
    while (offset + 8 <= end) {
      let size = dv.getUint32(offset);
      const type = String.fromCharCode(u8[offset + 4], u8[offset + 5], u8[offset + 6], u8[offset + 7]);
      let headerSize = 8;
      if (size === 1) {
        size = Number(dv.getUint32(offset + 8)) * 4294967296 + dv.getUint32(offset + 12);
        headerSize = 16;
      } else if (size === 0) {
        size = end - offset;
      }
      if (size <= 0 || offset + size > end) break;
      cb(type, offset, headerSize, size);
      offset += size;
    }
  }

  function parseTrak(dv, u8, trakOff, trakHs, trakSize) {
    const trak = {
      width: 0,
      height: 0,
      fps: 0,
      duration: 0,
      timescale: 0,
      durationSec: 0,
      handler: "",
      sampleCount: 0,
      chunkCount: 0,
      stscEntries: 0,
    };

    walkBoxes(dv, u8, trakOff + trakHs, trakOff + trakSize, function (type, off, hs, size) {
      if (type === "tkhd") {
        const version = dv.getUint8(off + hs);
        const base = off + hs + 4;
        const widthOffset = version === 1 ? base + 84 : base + 72;
        trak.width = Math.round(dv.getUint16(widthOffset) + dv.getUint16(widthOffset + 2) / 65536);
        trak.height = Math.round(
          dv.getUint16(widthOffset + 4) + dv.getUint16(widthOffset + 6) / 65536
        );
      } else if (type === "mdia") {
        walkBoxes(dv, u8, off + hs, off + size, function (t2, o2, h2, s2) {
          if (t2 === "mdhd") {
            const version = dv.getUint8(o2 + h2);
            const base = o2 + h2 + 4;
            if (version === 1) {
              trak.timescale = dv.getUint32(base + 16);
              trak.duration = Number(dv.getUint32(base + 20)) * 4294967296 + dv.getUint32(base + 24);
            } else {
              trak.timescale = dv.getUint32(base + 8);
              trak.duration = dv.getUint32(base + 12);
            }
          } else if (t2 === "hdlr") {
            trak.handler = String.fromCharCode(u8[o2 + h2 + 8], u8[o2 + h2 + 9], u8[o2 + h2 + 10], u8[o2 + h2 + 11]);
          } else if (t2 === "minf") {
            walkBoxes(dv, u8, o2 + h2, o2 + s2, function (t3, o3, h3, s3) {
              if (t3 !== "stbl") return;
              walkBoxes(dv, u8, o3 + h3, o3 + s3, function (t4, o4, h4, s4) {
                if (t4 === "stts") {
                  const entryCount = dv.getUint32(o4 + h4 + 4);
                  let totalSamples = 0;
                  let totalDelta = 0;
                  for (let i = 0; i < entryCount; i++) {
                    const entry = o4 + h4 + 8 + i * 8;
                    const count = dv.getUint32(entry);
                    const delta = dv.getUint32(entry + 4);
                    totalSamples += count;
                    totalDelta += count * delta;
                  }
                  if (totalDelta > 0 && trak.timescale > 0) {
                    trak.fps = (trak.timescale * totalSamples) / totalDelta;
                  }
                } else if (t4 === "stsc") {
                  trak.stscEntries = dv.getUint32(o4 + h4 + 4);
                } else if (t4 === "stsz") {
                  trak.sampleCount = dv.getUint32(o4 + h4 + 8);
                } else if (t4 === "stco" || t4 === "co64") {
                  trak.chunkCount = dv.getUint32(o4 + h4 + 4);
                }
              });
            });
          }
        });
      }
    });

    if (trak.timescale > 0) {
      trak.durationSec = trak.duration / trak.timescale;
    }
    // fallback untuk video panjang: jika stts gagal, hitung dari sampleCount/duration (akurat untuk VFR/long)
    if ((!trak.fps || trak.fps === 0) && trak.sampleCount > 0 && trak.durationSec > 0) {
      trak.fps = trak.sampleCount / trak.durationSec;
    }
    // fallback tambahan: jika masih 0, coba dari chunkCount/sampleCount
    if ((!trak.fps || trak.fps === 0) && trak.sampleCount > 0 && trak.timescale > 0 && trak.duration > 0) {
      trak.fps = (trak.sampleCount * trak.timescale) / trak.duration;
    }
    return trak;
  }

  function parseMp4(arrayBuffer) {
    const dv = new DataView(arrayBuffer);
    const u8 = new Uint8Array(arrayBuffer);
    const info = { majorBrand: "", brands: [], tracks: [], duration: 0, timescale: 0 };

    walkBoxes(dv, u8, 0, u8.length, function (type, off, hs, size) {
      if (type === "ftyp") {
        info.majorBrand = String.fromCharCode(u8[off + hs], u8[off + hs + 1], u8[off + hs + 2], u8[off + hs + 3]);
        for (let i = off + hs + 8; i + 4 <= off + size; i += 4) {
          info.brands.push(String.fromCharCode(u8[i], u8[i + 1], u8[i + 2], u8[i + 3]));
        }
      } else if (type === "moov") {
        walkBoxes(dv, u8, off + hs, off + size, function (t2, o2, h2, s2) {
          if (t2 === "mvhd") {
            const version = dv.getUint8(o2 + h2);
            const base = o2 + h2 + 4;
            if (version === 1) {
              info.timescale = dv.getUint32(base + 16);
              info.duration = Number(dv.getUint32(base + 20)) * 4294967296 + dv.getUint32(base + 24);
            } else {
              info.timescale = dv.getUint32(base + 8);
              info.duration = dv.getUint32(base + 12);
            }
          } else if (t2 === "trak") {
            info.tracks.push(parseTrak(dv, u8, o2, h2, s2));
          }
        });
      }
    });

    return info;
  }

  async function analyzeFile(file) {
    const buffer = await file.arrayBuffer();
    const u8 = new Uint8Array(buffer);
    const boxType = u8.length >= 8 ? String.fromCharCode(u8[4], u8[5], u8[6], u8[7]) : "";
    addLog(
      tr("logBufferRead", "Buffer terbaca: ") +
        buffer.byteLength.toLocaleString("id-ID") +
        " bytes" + tr("logBoxMagic", " | Box[0]: ") +
        (boxType || tr("logUnknown", "unknown")) +
        " \u2713"
    );
    const info = parseMp4(buffer);
    const video = info.tracks.find(function (t) {
      return t.handler === "vide";
    }) || info.tracks[0];
    let fps = video ? video.fps : 0;
    // fallback akurat untuk video panjang: jika stts gagal, hitung dari sampleCount/durationSec
    if ((!fps || fps === 0) && video && video.sampleCount > 0) {
      const durTmp = video.durationSec || (info.timescale > 0 ? info.duration / info.timescale : 0);
      if (durTmp > 0) fps = video.sampleCount / durTmp;
    }
    if (!fps || fps === 0) {
      // last resort: anggap 30fps biar tidak "Tidak terdeteksi" untuk video panjang
      const durTmp2 = video && video.durationSec ? video.durationSec : (info.timescale > 0 ? info.duration / info.timescale : 0);
      if (durTmp2 > 5) fps = 30;
    }
    const duration =
      video && video.durationSec
        ? video.durationSec
        : info.timescale > 0
        ? info.duration / info.timescale
        : 0;
    return {
      file: file,
      name: file.name,
      sizeMB: file.size / (1024 * 1024),
      fps: fps,
      duration: duration,
      width: video ? video.width : 0,
      height: video ? video.height : 0,
      brands: info.brands,
    };
  }

  function showModal() {
    els.analysisModal.hidden = false;
    document.body.style.overflow = "hidden";
  }

  function closeModal() {
    els.analysisModal.hidden = true;
    document.body.style.overflow = "";
  }

  function openDonateModal() {
    els.donateModal.hidden = false;
    document.body.style.overflow = "hidden";
  }

  function closeDonateModal() {
    els.donateModal.hidden = true;
    document.body.style.overflow = "";
  }

  function goToDonatePanel() {
    closeDonateModal();
    try{
      if(window.velardToolModal && window.velardToolModal.close) window.velardToolModal.close();
      var tb=document.getElementById("toolModalBackdrop");
      var tc=document.getElementById("toolModalCard");
      if(tb){ tb.hidden=true; tb.classList.remove("active"); }
      if(tc && !tc.hidden){ tc.hidden=true; tc.classList.remove("expanded","is-morphing"); document.body.classList.remove("tool-modal-open"); }
      document.body.style.overflow="";
    }catch(e){ console.warn(e); }
    if (window.velardActivatePanel) {
      window.velardActivatePanel('donate', true);
      return;
    }
    const fnav = document.querySelector('.floating-nav-item[data-panel="donate"]');
    if (fnav) { fnav.click(); return; }
    const nav = document.querySelector('.nav-item[data-panel="donate"]');
    if (nav) nav.click();
  }

  function setRowStatus(iconEl, valueEl, value, status) {
    valueEl.textContent = value;
    iconEl.textContent = status.icon;
    iconEl.className = "analysis-icon" + (status.ok ? " ok" : status.warn ? " warn" : " bad");
  }

  async function openAnalysisModal(file) {
    showModal();
    els.modalFileName.textContent = file.name;
    setRowStatus(els.fpsIcon, els.fpsValue, "Memproses...", { icon: "\u23F3", ok: false, warn: false });
    setRowStatus(els.resIcon, els.resValue, "Memproses...", { icon: "\u23F3", ok: false, warn: false });
    setRowStatus(els.sizeIcon, els.sizeValue, "Memproses...", { icon: "\u23F3", ok: false, warn: false });
    try {
      analysisData = await analyzeFile(file);
      const fps = analysisData.fps;
      const width = analysisData.width;
      const height = analysisData.height;
      const sizeMB = analysisData.sizeMB;
      setRowStatus(
        els.fpsIcon,
        els.fpsValue,
        fps > 0 ? fps.toFixed(2) + " fps" : "Tidak terdeteksi",
        makeStatus(fps > 0 && fps <= 120 && Number.isInteger(fps), fps > 0)
      );
      setRowStatus(
        els.resIcon,
        els.resValue,
        width > 0 ? width + " x " + height : "Tidak terdeteksi",
        makeStatus(width * height >= 1920 * 1080, width * height >= 1280 * 720)
      );
      setRowStatus(
        els.sizeIcon,
        els.sizeValue,
        sizeMB.toFixed(2) + " MB",
        makeStatus(sizeMB <= 1500, false)
      );
      addLog(
        tr("logAnalyzeDone", "Analisis selesai: ") +
          fps.toFixed(2) +
          " fps | " +
          width +
          " x " +
          height +
          " | " +
          sizeMB.toFixed(2) +
          " MB"
      );
    } catch (err) {
      addLog(tr("logAnalyzeFail", "Gagal menganalisis video: ") + err.message);
      setRowStatus(els.fpsIcon, els.fpsValue, tr("logFailed", "Gagal"), { icon: "\u274C", ok: false, warn: false });
      setRowStatus(els.resIcon, els.resValue, tr("logFailed", "Gagal"), { icon: "\u274C", ok: false, warn: false });
      setRowStatus(els.sizeIcon, els.sizeValue, tr("logFailed", "Gagal"), { icon: "\u274C", ok: false, warn: false });
    }
  }

  function proceedFromModal() {
    if (!analysisData) return;
    closeModal();
    els.processBtn.disabled = false;
    addLog(
      tr("logApproved", "Video disetujui. Siap diproses (V") +
        (state.version === "v1" ? "1" : "3") +
        " / Compress " +
        state.compress.toUpperCase() +
        ")."
    );
  }

  function cancelAnalysis() {
    closeModal();
    selectedFile = null;
    analysisData = null;
    resetFileUi();
    addLog(tr("logCanceled", "Analisis dibatalkan."));
  }

  function resetFileUi() {
    els.fileInput.value = "";
    els.fileInfo.hidden = true;
    els.fileName.textContent = "";
    els.fileMeta.textContent = "";
    els.processBtn.disabled = true;
    els.progressWrap.hidden = true;
    els.logHead.hidden = true;
    els.logArea.hidden = true;
    try { if (ffmpegInstance && typeof ffmpegInstance._resetProgress === 'function') ffmpegInstance._resetProgress(); } catch(e){ console.warn(e); }
    setProgress(0);
    setCompressGuard();
  }

  function handleFileSelected(file) {
    if (!file || !file.type.startsWith("video/")) {
      addLog(tr("logErrorNotVideo", "Error: \"") + (file ? file.name : tr("logFile", "File")) + tr("logNotVideo", "\" bukan file video."));
      return;
    }
    if (file.size > MAX_FILE_BYTES) {
      addLog(tr("logTooBig", "Error: File terlalu besar (") + formatBytes(file.size) + tr("logTooBig2", "). Maksimal 1500 MB."));
      return;
    }
    selectedFile = file;
    analysisData = null;
    setCompressGuard();
    els.fileName.textContent = file.name;
    els.fileMeta.textContent = formatBytes(file.size);
    els.fileInfo.hidden = false;
    els.processBtn.disabled = true;
    // fix: jangan tampilkan processing/log sebelum tombol proses ditekan + reset progress 99% stuck
    els.progressWrap.hidden = true;
    els.logHead.hidden = true;
    els.logArea.hidden = true;
    try { if (ffmpegInstance && typeof ffmpegInstance._resetProgress === 'function') ffmpegInstance._resetProgress(); } catch(e){ console.warn(e); }
    setProgress(0);
    const dev = getDeviceInfo();
    addLog(
      tr("logFileLabel", "File") + ": " + file.name +
        " | " + formatBytes(file.size) +
        " (" + file.size.toLocaleString("id-ID") + " bytes) | " +
        (file.type || tr("logUnknown", "unknown"))
    );
    const verLabel = state.version === "wmv" ? "WMV" : state.version === "fps" ? "FPS" : state.version === "binary" ? "BINARY" : state.version.toUpperCase();
    addLog(
      tr("logMethodLabel", "Metode") + ": " +
        verLabel +
        " | Compress " + state.compress.toUpperCase() + (state.fixAudio ? " | FixAudio ON" : "")
    );
    addLog(
      tr("logDeviceLabel", "Perangkat") + ": " + dev.browser +
        " / " + dev.os + " / " + dev.threads + " " + tr("logThreads", "thread") +
        " | " + tr("logSABLabel", "SAB") + ": " +
        (dev.sab ? tr("logSABAvail", "Tersedia") : tr("logSABUnavail", "Tidak tersedia"))
    );
    openAnalysisModal(file);
  }

  function setProcessing(on) {
    if (on) {
      // reset progress state tanpa merubah logika quality method
      try { if (ffmpegInstance && typeof ffmpegInstance._resetProgress === 'function') ffmpegInstance._resetProgress(); } catch(e){ console.warn(e); }
      setProgress(0);
      // juga reset fake progress polling state
      try { window._velardLastBusy = false; } catch(e){ console.warn(e); }
    }
    els.processBtn.disabled = on || !selectedFile;
    els.processBtnLabel.textContent = on ? tr("processing", "Memproses...") : tr("processBtn", "Proses Video");
    els.progressWrap.hidden = !on;
    els.uploadArea.classList.toggle("disabled", on);
    // blokir semua tombol QM semasa proses (sesuai request: tidak bisa pencet apapun)
    try{
      const qmCard = document.getElementById('qmCard');
      if(qmCard){
        qmCard.querySelectorAll('button, input, select, textarea').forEach(function(el){
          if(el===els.processBtn) return;
          if(on){ el.dataset.prevDisabled = el.disabled ? '1' : '0'; el.disabled=true; el.style.pointerEvents='none'; el.style.opacity='0.5'; }
          else { if(el.dataset.prevDisabled==='0') el.disabled=false; else if(el.dataset.prevDisabled==='1') el.disabled=true; else el.disabled=false; el.style.pointerEvents=''; el.style.opacity=''; delete el.dataset.prevDisabled; }
        });
        qmCard.style.pointerEvents = on ? 'none' : '';
        // keep processBtn and progress visible even when card disabled
        els.processBtn.style.pointerEvents = '';
        if(els.progressWrap) els.progressWrap.style.pointerEvents = 'auto';
      }
    }catch(e){ console.warn(e); }
    if (on) {
      els.logHead.hidden = false;
      els.logArea.hidden = false;
      setTimeout(function () {
        els.logArea.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }, 60);
    }
    setProcessingFlag(on);
  }

  async function onProcessClick() {
    if (!selectedFile || els.processBtn.disabled) return;
    // pastikan progress 0 di awal proses baru (fix 99% stuck)
    try { if (ffmpegInstance && typeof ffmpegInstance._resetProgress === 'function') ffmpegInstance._resetProgress(); } catch(e){ console.warn(e); }
    setProgress(0);
    setProcessing(true);
    let ok = false;
    try {
      await processVideo(selectedFile, state.version, state.compress);
      setProgress(100);
      ok = true;
    } catch (err) {
      addLog(tr("logError", "Error: ") + getErrorMessage(err));
    } finally {
      setProcessing(false);
    }
    if (ok) openDonateModal();
  }

  // 100% tiru sumber: helpers untuk FFmpeg loader (tiktok-quality-tool.js)
  function getLocalFFmpegBaseURL(){
    try{ return new URL('assets/ffmpeg', window.location.href).href.replace(/\/$/,''); }catch(e){ return window.location.origin + '/assets/ffmpeg'; }
  }
  function canShareSABWithWorker(){
    return new Promise(function(resolve){
      let w=null; const timer=setTimeout(function(){ if(w){try{w.terminate();}catch(e){ console.warn(e); }} resolve(false); },2000);
      try{
        if(typeof SharedArrayBuffer==='undefined' || typeof Worker==='undefined'){ clearTimeout(timer); return resolve(false); }
        const blob=new Blob(['self.onmessage=function(e){self.postMessage(1)}'],{type:'text/javascript'});
        w=new Worker(URL.createObjectURL(blob));
        w.onmessage=function(){ clearTimeout(timer); try{w.terminate();}catch(e){ console.warn(e); } resolve(true); };
        w.onerror=function(){ clearTimeout(timer); try{w.terminate();}catch(e){ console.warn(e); } resolve(false); };
        w.postMessage([new SharedArrayBuffer(8)]);
      }catch(e){ clearTimeout(timer); if(w){try{w.terminate();}catch(e){ console.warn(e); }} resolve(false); }
    });
  }
  async function supportsMultiThread(){
    if(isMobileDeviceLocal()) return false;
    if(typeof SharedArrayBuffer==='undefined' || typeof Atomics==='undefined') return false;
    if(window.crossOriginIsolated!==true) return false;
    return await canShareSABWithWorker();
  }
  function withTimeout(promise, ms, label){
    return new Promise(function(resolve,reject){
      const timer=setTimeout(function(){ reject(new Error((label||'Operation')+' timed out after '+Math.round(ms/1000)+'s')); }, ms);
      Promise.resolve(promise).then(function(v){ clearTimeout(timer); resolve(v); }, function(e){ clearTimeout(timer); reject(e instanceof Error?e:new Error(getErrorMessage(e))); });
    });
  }

  async function buildInlineWorkerURL() {
    const [constSrc, errorsSrc, workerSrc] = await Promise.all([
      fetch(FFMPEG_CONST_URL).then(function (res) { return res.text(); }),
      fetch(FFMPEG_ERRORS_URL).then(function (res) { return res.text(); }),
      fetch(FFMPEG_WORKER_URL).then(function (res) { return res.text(); }),
    ]);
    const inlined = constSrc + "\n" + errorsSrc + "\n" + workerSrc.replace(/import\s*\{[^}]*\}\s*from\s*"\.\/const\.js";?/g, "").replace(/import\s*\{[^}]*\}\s*from\s*"\.\/errors\.js";?/g, "");
    return URL.createObjectURL(new Blob([inlined], { type: "text/javascript" }));
  }

  async function loadFfmpeg() {
    if (ffmpegInstance) return ffmpegInstance;
    if (ffmpegLoading) return ffmpegLoading;
    ffmpegLoading = (async function () {
      const util = await import(UTIL_ESM_URL);
      const moduleFFmpeg = await import(FFMPEG_ESM_URL);
      const FFmpeg = moduleFFmpeg.FFmpeg;
      const toBlobURL = util.toBlobURL;
      if (!toBlobURL) throw new Error("FFmpeg Util tidak lengkap. Coba refresh halaman.");
      const isMultiThread = await supportsMultiThread();
      const localBaseURL = getLocalFFmpegBaseURL();
      const cdnBaseMT = 'https://cdn.jsdelivr.net/npm/@ffmpeg/core-mt@0.12.6/dist/umd';
      const cdnBaseST = 'https://cdn.jsdelivr.net/npm/@ffmpeg/core@0.12.6/dist/umd';
      addLog("[FFmpeg] Multi-threading: " + (isMultiThread ? "Enabled" : "Disabled"));
      const attempts=[];
      if(isMultiThread){
        attempts.push({label:'local assets (MT)', base:localBaseURL, core:'ffmpeg-core', mt:true, timeout:15000});
        attempts.push({label:'CDN (MT)', base:cdnBaseMT, core:'ffmpeg-core', mt:true, timeout:30000});
      }
      attempts.push({label:'local assets (ST)', base:localBaseURL, core:'ffmpeg-core-st', mt:false, timeout:20000});
      attempts.push({label:'CDN (ST)', base:cdnBaseST, core:'ffmpeg-core', mt:false, timeout:35000});
      // fallback to ESM CDN if UMD fails (Velard keep ESM as last resort)
      let lastErr=null;
      for(const attempt of attempts){
        let instance=null;
        try{
          addLog("  Loading FFmpeg Core WASM (" + (attempt.mt?"Multi-Thread":"Single-Thread")+", "+attempt.label+")...");
          const classWorkerURL = await buildInlineWorkerURL();
          // UMD core URLs via toBlobURL with timeout
          const coreURL = await withTimeout(toBlobURL(attempt.base+'/'+attempt.core+'.js','text/javascript'), attempt.timeout, attempt.label+' core download');
          const wasmURL = await withTimeout(toBlobURL(attempt.base+'/'+attempt.core+'.wasm','application/wasm'), attempt.timeout, attempt.label+' wasm download');
          const config={ coreURL, wasmURL, classWorkerURL };
          if(attempt.mt) config.workerURL = await withTimeout(toBlobURL(attempt.base+'/ffmpeg-core.worker.js','text/javascript'), attempt.timeout, attempt.label+' worker download');
          instance=new FFmpeg();
          instance._ffProgress=-1;
          instance._resetProgress=function(){ instance._ffProgress=-1; try{ setProgress(0);}catch(e){ console.warn(e); } };
          instance.on("progress", function(event){
            const pct=Math.round(event.progress*100);
            if(!isFinite(pct)||pct<=0) return;
            if(pct>=95 && instance._ffProgress<50) return;
            if(pct>instance._ffProgress) instance._ffProgress=pct;
            const capped=Math.min(instance._ffProgress,99);
            setProgress(capped);
            // realtime tools progress - monotonic, tidak turun (fix 10->7)
            try{
              const active = window.velardToolModal && typeof window.velardToolModal.getActive === 'function' ? window.velardToolModal.getActive() : null;
              if(active){
                const map={mp3:'Mp3', convert:'Convert', cut:'Cut', rescale:'Rescale'};
                const Cap=map[active];
                if(Cap){
                  const prev = toolProgressDisplayed[active] || 0;
                  if(capped > prev){
                    toolProgressDisplayed[active]=capped;
                    const fill=document.getElementById('tool'+Cap+'ProgressFill');
                    const pctEl=document.getElementById('tool'+Cap+'ProgressPct');
                    const sec=document.getElementById('tool'+Cap+'Progress');
                    const arrow=document.getElementById('toolArrow-'+active);
                    const closeB=document.getElementById('toolModalClose');
                    if(fill) fill.style.width=capped+'%';
                    if(pctEl) pctEl.textContent=capped+'%';
                    if(sec && sec.hidden) sec.hidden=false;
                    if(arrow) arrow.innerHTML='<span class="tool-card-progress-text">'+capped+'%</span>';
                    if(closeB && active===window.velardToolModal.getActive()) closeB.innerHTML='<span class="tool-card-progress-text">'+capped+'%</span>';
                  }
                }
              }
            }catch(e){ console.warn(e); }
          });
          await withTimeout(instance.load(config), attempt.timeout, attempt.label+' engine init');
          try{ URL.revokeObjectURL(classWorkerURL); }catch(e){ console.warn(e); }
          addLog("  FFmpeg Core WASM loaded from "+attempt.label+".");
          ffmpegInstance=instance;
          return instance;
        }catch(err){
          lastErr=err;
          if(instance){ try{instance.terminate();}catch(e){ console.warn(e); } }
          addLog("  "+attempt.label+" failed: "+getErrorMessage(err));
          // continue
        }
      }
      // last resort ESM CDN MT/ST (original Velard)
      try{
        const classWorkerURL = await buildInlineWorkerURL();
        const instance=new FFmpeg();
        instance._ffProgress=-1;
        instance._resetProgress=function(){ instance._ffProgress=-1; try{ setProgress(0);}catch(e){ console.warn(e); } };
        instance.on("progress", function(event){
          const pct=Math.round(event.progress*100); if(!isFinite(pct)||pct<=0) return; if(pct>=95&&instance._ffProgress<50) return; if(pct>instance._ffProgress) instance._ffProgress=pct;
          const capped=Math.min(instance._ffProgress,99); setProgress(capped);
          try{
            const active = window.velardToolModal && typeof window.velardToolModal.getActive === 'function' ? window.velardToolModal.getActive() : null;
            if(active){
              const map={mp3:'Mp3', convert:'Convert', cut:'Cut', rescale:'Rescale'};
              const Cap=map[active];
              if(Cap){
                const prev = toolProgressDisplayed[active] || 0;
                if(capped > prev){
                  toolProgressDisplayed[active]=capped;
                  const fill=document.getElementById('tool'+Cap+'ProgressFill');
                  const pctEl=document.getElementById('tool'+Cap+'ProgressPct');
                  const sec=document.getElementById('tool'+Cap+'Progress');
                  const arrow=document.getElementById('toolArrow-'+active);
                  const closeB=document.getElementById('toolModalClose');
                  if(fill) fill.style.width=capped+'%';
                  if(pctEl) pctEl.textContent=capped+'%';
                  if(sec && sec.hidden) sec.hidden=false;
                  if(arrow) arrow.innerHTML='<span class="tool-card-progress-text">'+capped+'%</span>';
                  if(closeB && active===window.velardToolModal.getActive()) closeB.innerHTML='<span class="tool-card-progress-text">'+capped+'%</span>';
                }
              }
            }
          }catch(e){ console.warn(e); }
        });
        const canUseMT = window.crossOriginIsolated===true;
        if(canUseMT){
          await instance.load({ classWorkerURL, coreURL: await toBlobURL(CORE_MT_URL,'text/javascript'), wasmURL: await toBlobURL(CORE_MT_WASM_URL,'application/wasm'), workerURL: await toBlobURL(CORE_MT_WORKER_URL,'text/javascript') });
          addLog(tr("logFfmpegLoaded","FFmpeg (")+tr("logMT","multi-thread")+tr("logFfmpegFromCdn",") dimuat dari CDN: ")+"SUCCESS");
        } else {
          await instance.load({ classWorkerURL, coreURL: await toBlobURL(CORE_ST_URL,'text/javascript'), wasmURL: await toBlobURL(CORE_ST_WASM_URL,'application/wasm') });
          addLog(tr("logFfmpegLoaded","FFmpeg (")+tr("logST","single-thread")+tr("logFfmpegFromCdn",") dimuat dari CDN: ")+"SUCCESS");
        }
        try{ URL.revokeObjectURL(classWorkerURL);}catch(e){ console.warn(e); }
        ffmpegInstance=instance;
        return instance;
      }catch(e){ /* fallthrough */ }
      throw lastErr || new Error('Failed to load FFmpeg WASM from all sources.');
    })();
    ffmpegLoading.catch(function (err) { addLog(tr("logFfmpegFail", "\u2717 Gagal memuat: ") + getErrorMessage(err)); ffmpegLoading = null; });
    return ffmpegLoading;
  }

  async function removeFfmpegFiles(ffmpeg, files) {
    for (const name of files) {
      try {
        await ffmpeg.deleteFile(name);
      } catch (err) {
        /* file tidak ada, abaikan */
      }
    }
  }

