  function buildVfString(width, height, fps, compressLevel) {
    // 100% tiru computeVideoProcessingOptions sumber (assets/scripts/Tools/tiktok-quality-tool.js)
    const lvl = compressLevel || state.compress || "1080p";
    let targetW = width || 1080;
    let targetH = height || 1920;
    const qualityShortSide = (lvl === "720p") ? 720 : (lvl === "1080p") ? 1080 : null;
    let resNeedsCompress = false;
    if (qualityShortSide) {
      const shortSide = Math.min(targetW, targetH);
      if (shortSide > 0) {
        const ratio = qualityShortSide / shortSide;
        targetW = Math.round(targetW * ratio);
        targetH = Math.round(targetH * ratio);
        resNeedsCompress = true;
      }
    }
    targetW = Math.floor(targetW / 2) * 2;
    targetH = Math.floor(targetH / 2) * 2;
    let scaleFilter = `scale=${targetW}:${targetH}:force_original_aspect_ratio=decrease,pad=${targetW}:${targetH}:(ow-iw)/2:(oh-ih)/2,format=yuv420p`;
    if (lvl === "off") {
      scaleFilter = "scale='trunc(iw/2)*2':'trunc(ih/2)*2'";
    }
    let targetFps = null;
    let fpsNeedsCompress = false;
    let isFractional = false;
    if (fps != null && fps > 0) {
      if (fps > 120) {
        targetFps = 120;
        fpsNeedsCompress = true;
      } else if (!Number.isInteger(fps) || Math.abs(fps - Math.round(fps)) > 0.05) {
        fpsNeedsCompress = true;
        isFractional = true;
        const r = Math.round(fps);
        if (Math.abs(fps - 59) < 2 || Math.abs(fps - 60) < 2) targetFps = 60;
        else if (Math.abs(fps - 29.97) < 1 || Math.abs(fps - 30) < 1) targetFps = 30;
        else if (Math.abs(fps - 23.976) < 1 || Math.abs(fps - 24) < 1) targetFps = 24;
        else targetFps = r;
      }
    }
    const vfParts = [scaleFilter];
    if (targetFps) vfParts.push("fps=fps=" + targetFps + ":round=near");
    return {
      scaleFilter: scaleFilter,
      vfString: vfParts.join(","),
      resNeedsCompress: resNeedsCompress,
      fpsNeedsCompress: fpsNeedsCompress,
      isFractional: isFractional,
      targetW: targetW,
      targetH: targetH,
      targetFps: targetFps,
    };
  }

  function isMobileDeviceLocal(){
    try{ return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile|Tablet/i.test(navigator.userAgent) || (navigator.platform==="MacIntel" && navigator.maxTouchPoints>1); }catch(e){ return false; }
  }
  async function compressV3WithFfmpeg(arrayBuffer, fileName, meta) {
    const ffmpeg = await loadFfmpeg();
    const ext = getFileExtension(fileName) || "mp4";
    const inputName = "input_" + Date.now() + "." + ext;
    const outputName = "output_" + Date.now() + ".mp4";
    const sizeMB = meta && meta.sizeMB ? meta.sizeMB : 0;
    const compressLvl = (meta && meta.compress) ? meta.compress : state.compress;
    const vfInfo = buildVfString(meta ? meta.width : 0, meta ? meta.height : 0, meta ? meta.fps : 0, compressLvl);
    const vfString = vfInfo.vfString;
    const hardwareThreads = navigator.hardwareConcurrency || 4;
    const threads = sizeMB > 50 ? "2" : String(Math.min(4, hardwareThreads));
    const fixAudio = !!(meta && meta.fixAudio) || state.fixAudio;
    addLog("[1/3] " + tr("logStep1", "Memuat data video..."));
    await ffmpeg.writeFile(inputName, new Uint8Array(arrayBuffer));
    addLog("[2/3] " + tr("logStep2", "Optimasi kualitas..."));
    const audioArgs = fixAudio ? ["-c:a","aac","-b:a","192k","-ar","48000","-ac","2"] : ["-c:a","aac","-b:a","192k"];
    const isMobileDev = isMobileDeviceLocal();
    const x264Preset = (isMobileDev || sizeMB > 50) ? "superfast" : "veryfast";
    const crfValue = (compressLvl === "720p") ? "20" : "19";
    const maxRate = (compressLvl === "720p") ? "14M" : "24M";
    const bufSize = (compressLvl === "720p") ? "21M" : "38M";
    const fpsVal = (meta && meta.fps) ? meta.fps : 30;
    const gopSize = String(Math.max(48, Math.min(240, Math.round((fpsVal||30)*2))));
    addLog(tr("logFilters", "FFmpeg filters: ") + vfString + (fixAudio ? " + fixAudio" : ""));
    addLog("  Encoder: libx264 " + x264Preset + " crf=" + crfValue + " maxrate=" + maxRate + " gop=" + gopSize);
    await ffmpeg.exec([
      "-y",
      "-i", inputName,
      "-threads", threads,
      "-map", "0:v:0",
      "-map", fixAudio ? "0:a:0" : "0:a:0?",
      "-dn",
      "-map_metadata", "-1",
      "-map_chapters", "-1",
      "-vf", vfString,
      "-vsync", "cfr",
      "-c:v", "libx264",
      "-preset", x264Preset,
      "-crf", crfValue,
      "-maxrate", maxRate,
      "-bufsize", bufSize,
      "-g", gopSize,
      "-pix_fmt", "yuv420p",
    ].concat(audioArgs).concat([
      "-movflags", "+faststart",
      outputName,
    ]));
    addLog("[3/3] " + tr("logStep3", "Encoding & menyimpan..."));
    const data = await ffmpeg.readFile(outputName);
    await removeFfmpegFiles(ffmpeg, [inputName, outputName]);
    return data;
  }

