  var HD_CONTAINERS = ["moov", "trak", "mdia", "minf", "stbl", "edts", "dinf", "udta", "meta", "ilst"];

  // === 1000% plek tiktok-quality-v3.js patch (watermark VelardTools) ===
  const FAKE_SAMPLE_BYTES_SRC = new Uint8Array([0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x00]);
  const FAKE_SAMPLE_SIZE_SRC = 8;
  const CONTAINER_BOXES_SRC = new Set(['moov','trak','mdia','minf','stbl','edts','dinf','udta','meta','ilst']);
  function _src_getBoxType(d,o){ return String.fromCharCode(d[o],d[o+1],d[o+2],d[o+3]); }
  function _src_assertU32(v,l){ if(!Number.isFinite(v)||v<0||v>0xffffffff) throw new Error(l+' out of uint32 range: '+v); }
  function _src_readBox(view,data,offset,end,parentPath){
    if(offset+8>end) return null;
    const smallSize=view.getUint32(offset,false);
    const type=_src_getBoxType(data,offset+4);
    let size=smallSize; let headerSize=8;
    if(smallSize===1){
      if(offset+16>end) return null;
      const high=view.getUint32(offset+8,false);
      const low=view.getUint32(offset+12,false);
      size=high*4294967296+low; headerSize=16;
    } else if(smallSize===0) size=end-offset;
    if(size<headerSize||offset+size>end) return null;
    return {type,offset,size,headerSize,contentStart:offset+headerSize,end:offset+size,path:parentPath?parentPath+'/'+type:type,data,view,children:[],prefixStart:offset+headerSize,prefixEnd:offset+headerSize};
  }
  function _src_childStartForBox(box){ return box.type==='meta'?box.contentStart+4:box.contentStart; }
  function _src_parseBoxes(data,view,start,end,parentPath){
    const boxes=[]; let offset=start;
    while(offset+8<=end){
      const box=_src_readBox(view,data,offset,end,parentPath||'');
      if(!box) break;
      if(CONTAINER_BOXES_SRC.has(box.type)){
        const childStart=_src_childStartForBox(box);
        if(childStart<=box.end){ box.prefixStart=box.contentStart; box.prefixEnd=childStart; box.children=_src_parseBoxes(data,view,childStart,box.end,box.path); }
      }
      boxes.push(box); offset=box.end;
    }
    return boxes;
  }
  function _src_findChild(box,type){ return box?box.children.find(c=>c.type===type)||null:null; }
  function _src_findDescendant(box,typePath){ let cur=box; for(const t of typePath){ cur=_src_findChild(cur,t); if(!cur) return null; } return cur; }
  function _src_findTopLevel(boxes,type){ return boxes.find(b=>b.type===type)||null; }
  function _src_handlerTypeForTrak(trak){ const hdlr=_src_findDescendant(trak,['mdia','hdlr']); if(!hdlr||hdlr.offset+20>hdlr.end) return null; return _src_getBoxType(hdlr.data,hdlr.offset+16); }
  function _src_getTimescale(trak){ const mdhd=_src_findDescendant(trak,['mdia','mdhd']); if(!mdhd) return 90000; const ver=mdhd.data[mdhd.offset+8]; return ver===0?mdhd.view.getUint32(mdhd.offset+20,false):mdhd.view.getUint32(mdhd.offset+28,false); }
  function _src_parseStsz(stsz){ const sampleSize=stsz.view.getUint32(stsz.offset+12,false); const count=stsz.view.getUint32(stsz.offset+16,false); if(sampleSize) return new Array(count).fill(sampleSize); const tableStart=stsz.offset+20; const sizes=[]; for(let i=0;i<count;i++) sizes.push(stsz.view.getUint32(tableStart+i*4,false)); return sizes; }
  function _src_parseStco(box){ const isCo64=box.type==='co64'; const count=box.view.getUint32(box.offset+12,false); const tableStart=box.offset+16; const itemSize=isCo64?8:4; const offsets=[]; for(let i=0;i<count;i++){ if(isCo64){ const high=box.view.getUint32(tableStart+i*8,false); const low=box.view.getUint32(tableStart+i*8+4,false); offsets.push(high*4294967296+low);} else offsets.push(box.view.getUint32(tableStart+i*4,false)); } return offsets; }
  function _src_parseStsc(stsc){ const count=stsc.view.getUint32(stsc.offset+12,false); const tableStart=stsc.offset+16; const rows=[]; for(let i=0;i<count;i++){ const off=tableStart+i*12; rows.push([stsc.view.getUint32(off,false),stsc.view.getUint32(off+4,false),stsc.view.getUint32(off+8,false)]);} return rows; }
  function _src_parseStts(stts){ const count=stts.view.getUint32(stts.offset+12,false); const tableStart=stts.offset+16; const entries=[]; for(let i=0;i<count;i++){ const off=tableStart+i*8; entries.push([stts.view.getUint32(off,false),stts.view.getUint32(off+4,false)]);} return entries; }
  function _src_makeBox(type,payload){ const size=8+payload.byteLength; _src_assertU32(size,type+'.size'); const box=new Uint8Array(size); const dv=new DataView(box.buffer); dv.setUint32(0,size,false); for(let i=0;i<4;i++) box[4+i]=type.charCodeAt(i); box.set(new Uint8Array(payload.buffer||payload,payload.byteOffset||0,payload.byteLength),8); return box; }
  function _src_concatBytes(parts){ let total=0; for(const p of parts) total+=(p?p.byteLength:0); const res=new Uint8Array(total); let off=0; for(const p of parts){ if(!p) continue; res.set(new Uint8Array(p.buffer||p,p.byteOffset||0,p.byteLength),off); off+=p.byteLength; } return res; }
  function _src_boxBytes(box){ return new Uint8Array(box.data.buffer, box.data.byteOffset+box.offset, box.size); }
